	//         "AskOrderCt":0,
	//         "Rolling24HrPxChangePercent":0,
	//     }
	//
	// fetchTickers
	//
	//     {
	//         "trading_pairs":"BTC_CAD",
	//         "last_price":75925.37,
	//         "lowest_ask":75926.63,
	//         "highest_bid":66.435340000000000000000000000,
