	//         "NotionalValue":2345.5251300000000000000000000,
	//         "NotionalHoldAmount":0,
	//         "TradeTime":637431618315686826
	//     }
	//
	// fetchOrderTrades
	//
	//     {
	//         "Side":"Sell",
	//         "OrderId":2543565235,
	//         "Price":18600.000000000000000000000000,
	//         "Quantity":0.0000000000000000000000000000,
